import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import BarraNavegacion from "./componentes/diseno/BarraNavegacion";
import DatosDelSostenedor from "./paginas/Sostenedor/DatosDelSostenedor";
import EstructuraDeCurso from "./paginas/Establecimientos/EstructuraDeCurso";
import AlumnosDelCurso from "./paginas/alumnos/AlumnosDelCurso";
import Login from "./paginas/auth"; // ✅ tu carpeta auth
import { AuthProvider, useAuth } from "./contexto/AuthContext"; // ✅ español

function ProtectedRoute({ children }) {
  const { isAuth, status } = useAuth();
  if (status !== "ready") return null; // opcional: spinner
  if (!isAuth) return <Navigate to="/login" replace />;
  return children;
}

function AdminRoute({ children }) {
  const { isAuth, status, hasRole } = useAuth();
  if (status !== "ready") return null;
  if (!isAuth) return <Navigate to="/login" replace />;
  if (!hasRole("admin")) return <Navigate to="/" replace />;
  return children;
}

function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <BarraNavegacion />
        <main>
          <Routes>
            {/* Login público */}
            <Route path="/login" element={<Login />} />

            {/* Rutas protegidas solo para Admin */}
            <Route
              path="/"
              element={
                <AdminRoute>
                  <DatosDelSostenedor />
                </AdminRoute>
              }
            />
            <Route
              path="/sostenedor"
              element={
                <AdminRoute>
                  <DatosDelSostenedor />
                </AdminRoute>
              }
            />
            <Route
              path="/establecimientos/:id/estructura"
              element={
                <AdminRoute>
                  <EstructuraDeCurso />
                </AdminRoute>
              }
            />
            <Route
              path="/establecimientos/:id/cursos/:cursoId/alumnos"
              element={
                <AdminRoute>
                  <AlumnosDelCurso />
                </AdminRoute>
              }
            />

            {/* Redirección por defecto */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </BrowserRouter>
    </AuthProvider>
  );
}

export default App;
